import { ProjectParamsSchema } from './schemas';
import { Router } from 'express';
import { z } from 'zod';
import { ProjectFolderPicker } from '../../services/ProjectFolderPicker';
import { ProjectNameSchema } from '../../services/ProjectRegistry';
import type { LibraryRouteServices } from './types';
import type { ProjectLibrarySnapshot } from '../../types/project-library';
import type {
  FolderSelectionResponse,
  LibraryProjectListResponse,
  LibraryProjectPreviewResponse,
  LibraryProjectRemovalResponse,
  LibraryProjectResponse,
  ProjectRuntimeResponse,
} from '../../types/api-responses';

const WorkspaceSchema = z.object({ projectPath: z.string().min(1) });
const ProjectUpdateSchema = z.object({ name: ProjectNameSchema }).strict();

export const createProjectRoutes = ({
  library,
  runtime,
  cardPreviews,
  folderPicker = new ProjectFolderPicker(),
  track,
  token,
  profiles,
}: LibraryRouteServices): Router => {
  const router = Router();
  router.get('/', async (_req, res) =>
    res.json((await library.snapshot()) satisfies ProjectLibrarySnapshot),
  );
  router.get('/projects', (req, res) => {
    if (req.headers.authorization !== `Bearer ${token}`)
      profiles?.sourceSync.start();
    return res.json({
      projects: library.listProjects(),
    } satisfies LibraryProjectListResponse);
  });
  router.patch('/projects/:projectId', track('project_rename'), (req, res) => {
    const { projectId } = ProjectParamsSchema.parse(req.params);
    const { name } = ProjectUpdateSchema.parse(req.body);
    res.json({
      project: library.registry.rename({ projectId, name }),
    } satisfies LibraryProjectResponse);
  });
  router.put('/projects/:projectId/pin', track('project_pin'), (req, res) => {
    const { projectId } = ProjectParamsSchema.parse(req.params);
    res.json({
      project: library.registry.setPinned({ projectId, isPinned: true }),
    } satisfies LibraryProjectResponse);
  });
  router.delete(
    '/projects/:projectId/pin',
    track('project_unpin'),
    (req, res) => {
      const { projectId } = ProjectParamsSchema.parse(req.params);
      res.json({
        project: library.registry.setPinned({ projectId, isPinned: false }),
      } satisfies LibraryProjectResponse);
    },
  );
  router.delete('/projects/:projectId', track('project_remove'), (req, res) => {
    const { projectId } = ProjectParamsSchema.parse(req.params);
    library.registry.remove(projectId);
    res.json({ projectId } satisfies LibraryProjectRemovalResponse);
  });
  router.get('/projects/:projectId/thumbnail', async (req, res) => {
    const { projectId } = ProjectParamsSchema.parse(req.params);
    library.registry.get(projectId);
    res.setHeader('Cache-Control', 'no-store');
    res.json({
      preview: (await cardPreviews?.get(projectId)) ?? null,
    } satisfies LibraryProjectPreviewResponse);
  });
  router.post(
    '/folder-selections',
    track('folder_select'),
    async (_req, res) => {
      res.json({
        projectPath: await folderPicker.pick(),
      } satisfies FolderSelectionResponse);
    },
  );
  router.post('/projects', track('project_open'), async (req, res) => {
    const body = WorkspaceSchema.parse(req.body);
    res
      .status(201)
      .json(
        (await library.prepare(
          body.projectPath,
        )) satisfies LibraryProjectResponse,
      );
  });
  router.patch(
    '/projects/:projectId/workspace',
    track('project_open'),
    async (req, res) => {
      const body = WorkspaceSchema.parse(req.body);
      res.json({
        project: await library.relink({
          projectId: ProjectParamsSchema.parse(req.params).projectId,
          projectPath: body.projectPath,
        }),
      } satisfies LibraryProjectResponse);
    },
  );
  router.post(
    '/projects/:projectId/runtime',
    track('workspace_open'),
    async (req, res) => {
      res.json(
        (await runtime.activate(
          ProjectParamsSchema.parse(req.params).projectId,
        )) satisfies ProjectRuntimeResponse,
      );
    },
  );
  return router;
};
